(function(){'use strict';
/* =====================================================================
   CENTRO DE AYUDA (AYU) y ASISTENTE DE AYUDA (IAR-9 a IAR-11)
   - Botón de ayuda en la cabecera para todos los roles y pantallas.
   - Ayuda del producto (la publica GestiaHR desde la consola) + artículos de la organización.
   - Asistente de ayuda SIMULADO: busca en los artículos visibles con reglas escritas y cita la fuente.
     Se habilita en tres niveles: plan (función de la consola), organización (encendido y roles) y usuario.
   ===================================================================== */
const PV='ayuda.articulos.ver',PO='ayuda.organizacion.administrar',PC='ayuda.asistente.administrar',PI='ayuda.indicadores.ver';
const FLAG='ayuda.asistente_ia',VER='1.8';
const $=id=>document.getElementById(id);
if(typeof ICONS==='object'&&!ICONS.help)ICONS.help='<circle cx="12" cy="12" r="9"/><path d="M9.6 9.2a2.5 2.5 0 1 1 3.4 2.3c-.6.3-1 .8-1 1.5v.6"/><path d="M12 16.8h.01"/>';
const U=(k,d)=>ui[k]==null?(ui[k]=d):ui[k];
const nrm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
const STOP=new Set('el la los las un una unos unas de del al a en y o u que como cual cuales cuando donde quien para por con sin mi mis tu tus su sus se me te le lo es son hay puedo puede hago hacer debo tengo esta este esto estos estas ese esa eso mas muy ya si no le les nos sobre entre desde hasta cada todo toda todos todas otro otra quiero necesito saber ver veo favor ayuda trabajo empresa pido pedir llevar usar tener dar hago encuentro encontrar alguien algo gestiahr'.split(' '));
const stem=w=>w.length>4&&w.endsWith('es')?w.slice(0,-2):w.length>3&&w.endsWith('s')?w.slice(0,-1):w;
const toks=s=>nrm(s).split(/[^a-z0-9ñ]+/).filter(w=>w.length>2&&!STOP.has(w)).map(stem);
const MODL={base:'General',tiempo:'Tiempo',nomina:'Nómina',documentos:'Documentos',mesa:'Mesa de ayuda',reclutamiento:'Talento',sst:'SST',gastos:'Gastos',plataforma:'Configuración',ia:'Asistente de IA'};
const ROLN=id=>((T().roles||[]).find(r=>r.id===id)||{}).nombre||id;

/* ---------- ayuda del producto (global: la publica GestiaHR) ---------- */
const A_=(id,titulo,modulo,roles,rutas,tipo,resumen,pasos,claves)=>({id,titulo,modulo,roles,rutas,tipo,resumen,pasos,claves:claves||'',version:VER,estado:'Publicado',actualizado:addDays(TODAY,-12),hist:[{version:'1.7',fecha:addDays(TODAY,-70),titulo}]});
function PROD(){if(!db.ay_prod)db.ay_prod=[
 A_('ap1','Cómo usar la ayuda y el asistente','base',['todos'],[],'Guía','El botón de ayuda está arriba en todas las pantallas. Abre primero los artículos de la pantalla en la que estás.',['Pulsa el botón de ayuda (el signo de interrogación) en la barra superior.','En «Esta pantalla» verás los artículos de lo que estás haciendo; en «Guías» puedes buscar cualquier tema.','Si tu empresa lo habilitó, en «Asistente» puedes escribir tu duda con tus palabras: responde con los artículos de la ayuda y te dice de dónde sacó la respuesta.','Si nada te sirve, usa «Derivar a RRHH» y tu consulta llega como solicitud.'],'ayuda asistente preguntar buscar soporte'),
 A_('ap2','Tu inicio y tus pendientes','base',['todos'],['inicio','pl_pend','pl_tareas'],'Pantalla','El inicio muestra lo que te toca hoy y «Pendientes» junta todo lo que espera tu acción.',['En Inicio ves tus saldos, avisos y accesos directos según tu rol.','En Pendientes aparecen las aprobaciones, firmas y tareas que esperan tu respuesta.','Al aprobar o rechazar, la persona recibe el aviso al instante.'],'inicio pendientes tareas bandeja aprobar'),
 A_('ap3','Cómo pedir vacaciones','tiempo',['todos'],['ti_vacaciones'],'Guía','Las vacaciones se piden desde Tiempo → Vacaciones y las aprueba tu jefe.',['Entra a Tiempo → Vacaciones y pulsa «Solicitar vacaciones».','Elige las fechas: el sistema calcula los días y muestra tu saldo disponible.','Envía la solicitud: tu jefe la recibe en sus Pendientes.','Cuando la aprueben, la verás en el calendario del equipo y en tu saldo.'],'vacaciones solicitar pedir dias descanso saldo programar'),
 A_('ap4','Cómo aprobar las solicitudes de tu equipo','base',['r_mgr','r_rrhh','r_admin'],['pl_pend','pl_aprob'],'Guía','Las solicitudes de tu equipo llegan a Pendientes; puedes aprobarlas o rechazarlas con un comentario.',['Abre Pendientes desde el menú o desde la campana.','Revisa el detalle: fechas, saldo y cruces con el equipo.','Aprueba o rechaza; si rechazas, explica el motivo.','No puedes aprobar tus propias solicitudes: esas las aprueba tu jefe.'],'aprobar rechazar equipo solicitudes jefe manager'),
 A_('ap5','Cómo registrar una ausencia o un descanso médico','tiempo',['todos'],['ti_ausencias'],'Guía','Las ausencias y permisos se registran en Tiempo → Ausencias y permisos, con su sustento.',['Entra a Tiempo → Ausencias y permisos y pulsa «Registrar».','Elige el tipo (descanso médico, licencia, permiso) y las fechas.','Adjunta el sustento cuando el tipo lo pida, por ejemplo el certificado médico.','RRHH valida la ausencia y se refleja en la asistencia y en la planilla.'],'ausencia permiso descanso medico licencia certificado falta'),
 A_('ap6','Cómo marcar asistencia y pedir una corrección','tiempo',['todos'],['ti_asistencia','cx_kiosko'],'Guía','La marcación se hace desde la web, el móvil o el kiosko; si te olvidaste de marcar, pides una corrección.',['Marca tu entrada y salida desde Tiempo → Asistencia o desde el kiosko de tu sede.','Si olvidaste marcar, abre el día y pulsa «Pedir corrección» con el motivo.','Tu jefe aprueba la corrección; la marcación original no se borra.'],'marcar marcacion asistencia entrada salida tardanza correccion olvide'),
 A_('ap7','Dónde ver y descargar tu boleta de pago','nomina',['todos'],['no_mis'],'Guía','Tus boletas están en Nómina → Mis boletas, con su constancia de entrega.',['Entra a Nómina → Mis boletas.','Elige el periodo y abre la boleta.','Al abrirla queda la constancia de que la recibiste.'],'boleta pago recibo sueldo descargar mis boletas'),
 A_('ap8','Entender tu boleta: ingresos, descuentos y aportes','nomina',['todos'],['no_mis'],'Preguntas frecuentes','La boleta separa lo que ganas, lo que se te descuenta y lo que aporta tu empleador.',['Ingresos: sueldo, asignación familiar, horas extra y otros conceptos del mes.','Descuentos: aporte a tu AFP u ONP, renta de quinta categoría y otros descuentos autorizados.','Aportes del empleador: EsSalud y otros; no se descuentan de tu sueldo.','Si el neto cambió respecto del mes anterior, la boleta explica qué conceptos lo movieron.'],'boleta descuento afp onp essalud quinta neto ingreso aporte cambio'),
 A_('ap9','Calcular, aprobar y cerrar la planilla del mes','nomina',['r_pay','r_admin'],['no_periodos'],'Guía','La planilla se calcula por periodo, se revisa, la aprueba otra persona y luego se cierra.',['Abre Nómina → Planilla y elige el periodo.','Carga las incidencias y pulsa «Calcular».','Revisa las diferencias con el mes anterior y corrige lo necesario.','Envía a aprobación: quien calculó no puede aprobar.','Con la aprobación, cierra el periodo y publica las boletas.'],'planilla calcular cerrar periodo aprobar nomina incidencias'),
 A_('ap10','Gratificaciones y CTS','nomina',['r_pay','r_admin','r_rrhh'],['no_beneficios'],'Guía','Los beneficios sociales se calculan en Nómina → Beneficios sociales con los parámetros legales vigentes.',['Entra a Nómina → Beneficios sociales.','Elige el proceso (gratificación o CTS) y el periodo.','Revisa el cálculo por colaborador y apruébalo.','La CTS genera el archivo para los bancos.'],'gratificacion cts beneficios sociales deposito'),
 A_('ap11','Registrar a un nuevo colaborador','base',['r_rrhh','r_admin'],['colaboradores'],'Guía','El alta se hace en Personas → Colaboradores con los datos de la persona y de su relación laboral.',['Pulsa «Nuevo colaborador» en Personas → Colaboradores.','Completa los datos personales y el documento de identidad.','Completa puesto, sede, jefe, contrato y sueldo si tu rol lo permite.','Al guardar se crea la ficha y se avisa a los módulos que lo necesitan.'],'alta nuevo colaborador ingreso contratar registrar ficha'),
 A_('ap12','Actualizar tus datos personales','base',['todos'],['inicio'],'Guía','Puedes pedir cambios de tus datos desde tu ficha; RRHH los valida.',['Abre tu ficha desde Inicio → «Ver mi ficha».','Pulsa «Editar» en la sección que quieres cambiar.','Adjunta el sustento si te lo pide, por ejemplo para un cambio de dirección.','RRHH revisa el cambio y te avisa cuando quede aplicado.'],'datos personales direccion telefono actualizar cambio ficha cuenta bancaria'),
 A_('ap13','Firmar documentos','documentos',['todos'],['ex_firma','ex_docs'],'Guía','Los documentos que debes firmar te llegan a Pendientes y a Operaciones → Firma electrónica.',['Abre el documento desde Pendientes o desde Firma electrónica.','Revísalo completo antes de firmar.','Firma: queda la constancia con fecha y hora.'],'firmar firma documento contrato constancia'),
 A_('ap14','Hacer una consulta o pedir un certificado a RRHH','mesa',['todos'],['ex_mesa'],'Guía','Las consultas a RRHH se hacen en Experiencia → Mesa de ayuda y tienen un plazo de respuesta.',['Entra a Experiencia → Mesa de ayuda y pulsa «Nueva solicitud».','Elige la categoría y escribe tu consulta.','Sigue el estado y responde si RRHH te pide información.'],'consulta certificado constancia rrhh solicitud mesa ticket'),
 A_('ap15','Crear roles y dar permisos','base',['r_admin'],['roles','usuarios'],'Guía','Los permisos se dan por rol; un rol personalizado nace sin permisos.',['Entra a Seguridad → Roles y permisos.','Duplica un rol del sistema o crea uno nuevo.','Marca los permisos y el alcance (toda la organización, sede, equipo o lo propio).','Asigna el rol a los usuarios en Seguridad → Usuarios.'],'rol roles permisos usuario acceso alcance seguridad'),
 A_('ap16','Revisar la auditoría y los accesos a datos sensibles','base',['r_admin','r_aud'],['auditoria'],'Guía','La auditoría guarda quién cambió qué y cuándo; los accesos a datos sensibles tienen su propio registro.',['Entra a Seguridad → Auditoría.','Filtra por fecha, usuario o módulo.','En la pestaña Accesos ves quién consultó sueldos, salud u otros datos sensibles.'],'auditoria accesos registro cambios sensible'),
 A_('ap17','Importar colaboradores desde Excel','plataforma',['r_admin','r_rrhh'],['pl_import'],'Guía','La importación siempre pasa por validación y vista previa antes de guardar.',['Entra a Configuración → Importar datos.','Sube el archivo o usa la plantilla de ejemplo.','Revisa el mapeo de columnas y los errores por fila.','Confirma: solo se importan las filas válidas.'],'importar excel archivo carga masiva plantilla'),
 A_('ap18','Publicar una vacante','reclutamiento',['r_rec','r_rrhh','r_admin'],['ta_reclu'],'Guía','Las vacantes nacen de una posición aprobada y se publican en el portal de empleos.',['Entra a Talento → Reclutamiento y pulsa «Nueva vacante».','Elige la posición y completa la descripción.','Envíala a aprobación; al aprobarse, publícala en el portal.'],'vacante publicar reclutamiento candidato portal empleo'),
 A_('ap19','Reportar un accidente o incidente','sst',['todos'],['op_sstEventos'],'Guía','Todo accidente o incidente se registra en SST → Accidentes e incidentes el mismo día.',['Entra a SST → Accidentes e incidentes y pulsa «Registrar».','Indica qué pasó, dónde y a quién afectó.','El área de SST investiga y registra las medidas.'],'accidente incidente sst seguridad reportar lesion'),
 A_('ap20','Registrar un gasto o viático','gastos',['todos'],['op_gastos'],'Guía','Los gastos se registran con su comprobante y los aprueba tu jefe.',['Entra a Operaciones → Gastos y pulsa «Nuevo gasto».','Adjunta el comprobante y elige la categoría.','Envíalo: tu jefe lo aprueba y finanzas lo paga.'],'gasto viatico reembolso comprobante rendicion'),
 A_('ap21','Configurar la ayuda y el asistente','base',['r_admin','r_rrhh'],['ay_config'],'Guía','El administrador decide si el asistente está encendido, para qué roles y con qué límite de preguntas.',['Entra a Configuración → Ayuda y asistente.','En «Asistente» enciéndelo o apágalo y elige los roles habilitados.','En «Artículos de la organización» publica tus políticas internas: la ayuda y el asistente las usan.','En «Consultas» revisa las preguntas sin respuesta para mejorar tus artículos.'],'configurar asistente encender apagar activar desactivar roles articulos politicas'),
 A_('ap22','Novedades de la versión '+VER,'base',['todos'],[],'Novedades','Qué cambió en esta versión de GestiaHR.',['Nuevo centro de ayuda en todas las pantallas, con ayuda de la pantalla actual y buscador.','Asistente de ayuda: responde con los artículos de la ayuda y cita la fuente.','Tu empresa puede publicar sus propias políticas en la ayuda.'],'novedades version cambios nuevo')];
 return db.ay_prod}

/* ---------- disponibilidad por plan (función de la consola) ---------- */
const plApi=()=>(MODS.find(m=>m.id==='plataforma')||{}).api;
function ensureFlag(){const a=plApi();if(!a||!a.PL)return null;const P=a.PL();if(!P.flags.some(f=>f.clave===FLAG))P.flags.push({id:'ff_ay',clave:FLAG,nombre:'Asistente de ayuda con IA',desc:'Permite que la organización encienda el asistente del centro de ayuda. Luego lo enciende o apaga su administrador y elige los roles.',activo:true,todas:false,tenants:[],planes:['pln2','pln3'],paises:[],beta:false});return P}
function planAllows(tid){const P=ensureFlag();if(!P)return true;const f=P.flags.find(x=>x.clave===FLAG);if(!f||!f.activo)return false;if(f.todas)return true;
 tid=tid||session.tenantId;const s=P.subs[tid]||{},te=db.tenants.find(x=>x.id===tid)||{};
 return f.tenants.includes(tid)||(!!s.planId&&f.planes.includes(s.planId))||(f.beta&&!!s.beta)||f.paises.includes(te.pais)}
const CFG=()=>T().ay_cfg;
const asistOn=()=>planAllows()&&CFG().asistente&&CFG().roles.includes(me().rolId);
const hoyN=()=>T().ay_log.filter(l=>l.uid===me().id&&l.ts.slice(0,10)===TODAY).length;

/* ---------- visibilidad (RN-AYU-01, RN-AYU-03) ---------- */
const rolOk=rs=>rs.includes('todos')||rs.includes(me().rolId);
const rutaOk=r=>{try{return allowed(r)}catch(e){return false}};
const pVis=a=>a.estado==='Publicado'&&(a.modulo==='base'||modOn(a.modulo))&&rolOk(a.roles)&&(!a.rutas.length||a.tipo==='Novedades'||a.rutas.some(rutaOk));
const oVis=a=>a.estado!=='Borrador'&&a.estado!=='Archivado'&&rolOk(a.audiencia);
const porRevisar=a=>a.estado==='Publicado'&&a.revision&&a.revision<TODAY;
function fuentes(){const p=PROD().filter(pVis).map(a=>({k:'p:'+a.id,id:a.id,src:'Ayuda de GestiaHR',titulo:a.titulo,resumen:a.resumen,pasos:a.pasos,claves:a.claves,rutas:a.rutas,tipo:a.tipo,modulo:a.modulo,version:'Versión '+a.version}));
 const o=T().ay_org.filter(oVis).map(a=>({k:'o:'+a.id,id:a.id,src:tenant().nombre.replace(/\s*\(.*\)/,''),titulo:a.titulo,resumen:a.cuerpo.split('\n')[0],pasos:a.cuerpo.split('\n').slice(1).filter(Boolean),claves:a.categoria,rutas:[],tipo:'Política de la empresa',modulo:'org',version:'Versión '+a.version+(porRevisar(a)?' · por revisar':'')}));
 const k=modOn('mesa')?(T().ex_kb||[]).filter(a=>a.activo).map(a=>({k:'k:'+a.id,id:a.id,src:'Mesa de ayuda',titulo:a.titulo,resumen:String(a.cuerpo||'').split(/(?<=\.)\s/)[0],pasos:String(a.cuerpo||'').split(/(?<=\.)\s/).slice(1),claves:(a.claves||'')+' '+(a.categoria||''),rutas:['ex_mesa'],tipo:'Base de conocimiento',modulo:'mesa',version:''})):[];
 return p.concat(o,k)}
function score(f,qt){let s=0,m=0;const ti=toks(f.titulo),cl=toks(f.claves),bo=toks(f.resumen+' '+f.pasos.join(' '));qt.forEach(w=>{let h=0;if(ti.includes(w))h+=3;if(cl.includes(w))h+=2;if(bo.includes(w))h+=1;if(h)m++;s+=h});return {s,m}}
/* relevancia: al menos la mitad de las palabras con contenido de la pregunta deben aparecer en el artículo (evita respuestas por coincidencias sueltas) */
function buscar(q){const qt=[...new Set(toks(q))];if(!qt.length)return[];return fuentes().map(f=>({f,...score(f,qt)})).filter(x=>x.s>=2&&x.m/qt.length>=0.5).sort((a,b)=>b.m-a.m||b.s-a.s).map(x=>x.f)}
function regBusq(q,n,src){T().ay_busq.unshift({ts:new Date().toISOString(),q:q.slice(0,120),pantalla:ui.ay_ctx||'',rol:me().rolId,n,src});cap(T().ay_busq,400)}
const cap=(a,n)=>{if(a.length>n)a.length=n};
const navLabel=r=>{if(!r)return'';for(const g of navGroups())for(const i of g[2])if(i[0]===r)return (g[0]?g[0]+' → ':'')+i[1];return r==='ficha'?'Ficha del colaborador':r==='ay_centro'?'Centro de ayuda':r};

/* ---------- vistas del centro de ayuda ---------- */
const VOT=()=>T().ay_votos;
function artCard(f,compact){const v=VOT()[f.k]||{},mine=v[me().id];
 return `<div class="panel"><div class="pb"><div class="row" style="justify-content:space-between;align-items:flex-start;gap:8px"><div style="min-width:0;flex:1"><b>${esc(f.titulo)}</b><div class="muted" style="font-size:12px">${esc(f.src)} · ${esc(f.tipo)}${f.version?' · '+esc(f.version):''}</div></div>${pill(MODL[f.modulo]||(f.modulo==='org'?'Tu empresa':'General'),f.modulo==='org'?'acc':'')}</div>
 <p style="margin:8px 0">${esc(f.resumen)}</p>${compact?'':`<ol style="margin:0 0 8px 18px;padding:0">${f.pasos.map(p=>`<li style="margin:3px 0">${esc(p)}</li>`).join('')}</ol>`}
 <div class="row" style="gap:6px;flex-wrap:wrap">${compact?`<button class="btn s" data-a="ay_art" data-k="${f.k}">Leer</button>`:''}${f.rutas.filter(rutaOk).slice(0,1).map(r=>`<button class="btn s" data-a="ay_ir" data-r="${r}">Ir a ${esc(navLabel(r))}</button>`).join('')}
 <span class="muted" style="font-size:12px">¿Te sirvió?</span><button class="btn s${mine===1?' p':''}" data-a="ay_voto" data-k="${f.k}" data-v="1" aria-pressed="${mine===1}">Sí</button><button class="btn s${mine===-1?' p':''}" data-a="ay_voto" data-k="${f.k}" data-v="-1" aria-pressed="${mine===-1}">No</button></div></div></div>`}
function derivBox(q){return `<div class="note" style="margin-top:10px"><b>¿No resolviste tu duda?</b> Puedes enviarla a RRHH con lo que consultaste.${can(PC)?' Como administrador, también puedes escribir al soporte de GestiaHR.':''}<div class="row" style="margin-top:8px;gap:6px"><button class="btn s p" data-a="ay_derivar" data-q="${esc(q||'')}">Derivar a RRHH</button>${can(PC)?`<button class="btn s" data-a="ay_soporte" data-q="${esc(q||'')}">Escribir a soporte de GestiaHR</button>`:''}</div></div>`}

function vCentro(){const ctx=ui.ay_ctx||'inicio',on=asistOn(),tabs=[['pant','Esta pantalla'],['guias','Guías'],...(on?[['asis','Asistente']]:[]),['mis','Mis consultas']];
 let tab=U('ay_tab','pant');if(!tabs.some(t=>t[0]===tab))tab=ui.ay_tab='pant';
 const head=pageHead('Ayuda','Centro de ayuda',`<button class="btn" data-a="ay_volver">Volver a ${esc(navLabel(ctx)||'Inicio')}</button>`,'Guías de GestiaHR y políticas de tu empresa para tu rol: '+esc(role().nombre)+'.');
 const tb=`<div class="tabs">${tabs.map(t=>`<button class="tab ${t[0]===tab?'on':''}" data-a="ay_tab" data-t="${t[0]}">${t[1]}</button>`).join('')}</div>`;
 let body='';
 if(tab==='pant'){const fs=fuentes().filter(f=>f.rutas.includes(ctx));
  body=`<p class="muted">Artículos de <b>${esc(navLabel(ctx))}</b>.</p>`+(fs.length?fs.map(f=>artCard(f)).join(''):emptyState('Esta pantalla aún no tiene artículos propios','Busca tu tema en «Guías»'+(on?' o pregúntale al asistente.':'.'),`<button class="btn p" data-a="ay_tab" data-t="${on?'asis':'guias'}">${on?'Preguntar al asistente':'Ir a Guías'}</button>`))+derivBox('Duda en '+navLabel(ctx));
 }else if(tab==='guias'){const q=ui.ay_q||'',fs=q?buscar(q):fuentes(),nov=fuentes().filter(f=>f.tipo==='Novedades');
  const grp={};fs.filter(f=>f.tipo!=='Novedades').forEach(f=>{const g=f.modulo==='org'?'Políticas de tu empresa':(MODL[f.modulo]||'General');(grp[g]=grp[g]||[]).push(f)});
  body=`<div class="row" style="margin-bottom:10px"><input class="in" id="ay_q" placeholder="Busca un tema: vacaciones, boleta, marcar…" value="${esc(q)}" autocomplete="off" style="flex:1;min-width:0" aria-label="Buscar en la ayuda">${q?'<button class="btn" data-a="ay_qx">Limpiar</button>':''}</div>`+
  (q&&!fs.length?emptyState('No encontramos artículos para «'+esc(q)+'»','Prueba con otras palabras'+(on?', pregúntale al asistente':'')+' o deriva tu duda a RRHH.',on?`<button class="btn p" data-a="ay_preguntar" data-q="${esc(q)}">Preguntar al asistente</button>`:'')+derivBox(q):
  (!q&&nov.length?`<div class="panel"><div class="ph"><h2>Novedades</h2></div><div class="pb">${nov.map(f=>`<b>${esc(f.titulo)}</b><ul style="margin:6px 0 0 18px;padding:0">${f.pasos.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`).join('')}<div class="row" style="margin-top:8px"><button class="btn s" data-a="ay_tour">Ver el recorrido de mi rol</button></div></div></div>`:'')+
  Object.keys(grp).map(g=>`<h3 style="margin:14px 0 6px">${esc(g)}</h3>`+grp[g].map(f=>artCard(f,true)).join('')).join(''));
 }else if(tab==='asis'){body=vAsis()}
 else{const mis=T().ay_der.filter(d=>d.uid===me().id);
  body=mis.length?`<div class="panel"><div class="tw"><table><thead><tr><th>Consulta</th><th>Enviada a</th><th>Fecha</th><th>Estado</th></tr></thead><tbody>${mis.map(d=>`<tr><td style="min-width:220px">${esc(d.pregunta)}${d.codigo?`<div class="mono muted">${esc(d.codigo)}</div>`:''}${d.respuesta?`<div class="note" style="margin-top:6px">${esc(d.respuesta)}</div>`:''}</td><td>${esc(d.destino)}</td><td class="num">${fd(d.ts.slice(0,10))}</td><td>${pill(d.estado,d.estado==='Respondida'?'ok':'acc')}</td></tr>`).join('')}</tbody></table></div></div>`
   :emptyState('Aún no derivaste consultas','Cuando la ayuda no resuelva tu duda, usa «Derivar a RRHH» y aquí verás su estado.','')}
 return head+tb+body}

function vAsis(){const ch=U('ay_chat',[]),lim=CFG().limite,n=hoyN();
 return `<div class="note">${esc(CFG().aviso)}</div>
 <div class="panel"><div class="pb" id="ay_conv" style="display:flex;flex-direction:column;gap:10px">${ch.length?ch.map(m=>`<div style="align-self:flex-end;max-width:85%;background:var(--accent-soft);padding:8px 12px;border-radius:12px">${esc(m.q)}</div><div style="max-width:95%;background:var(--surface2);padding:10px 12px;border-radius:12px">${m.a}</div>`).join(''):`<div class="muted">Pregunta con tus palabras, por ejemplo: «¿cómo pido vacaciones?», «¿dónde veo mi boleta?» o «¿qué es la CTS?».</div>`}</div></div>
 <div class="row" style="gap:6px"><input class="in" id="ay_pq" placeholder="Escribe tu pregunta…" autocomplete="off" style="flex:1;min-width:0" aria-label="Pregunta al asistente"><button class="btn p" data-a="ay_ask">Preguntar</button></div>
 <div class="muted" style="font-size:12px;margin-top:6px">Asistente simulado: busca solo en los artículos que puedes ver y no consulta tus datos. ${lim?`Te quedan ${Math.max(0,lim-n)} de ${lim} preguntas hoy.`:''}</div>`}

const PERSONAL=[[/(cuant[oa]s?|mis?) .*dias? .*(vacaciones|me quedan|tengo|pendientes)|saldo de vacaciones|mi saldo/,'tu saldo de vacaciones','ti_vacaciones'],[/(cuanto gano|mi sueldo|mi neto|mi boleta|me pagaron|me depositaron|mi pago)/,'tu sueldo y tus boletas','no_mis'],[/(mis marcaciones|mis tardanzas|cuantas tardanzas)/,'tus marcaciones','ti_asistencia']];
function responder(q){const t=T(),qn=nrm(q),fs=buscar(q),top=fs.slice(0,2);let a='',ok=false;
 const per=PERSONAL.find(p=>p[0].test(qn));
 if(per){a+=`<p>En esta versión el asistente no consulta datos personales. Puedes ver ${per[1]} en <b>${esc(navLabel(per[2]))}</b>.</p>${rutaOk(per[2])?`<div class="row"><button class="btn s" data-a="ay_ir" data-r="${per[2]}">Ir a ${esc(navLabel(per[2]))}</button></div>`:''}`;ok=true}
 if(top.length){const f=top[0];ok=true;
  a+=`<p>Según <b>«${esc(f.titulo)}»</b> (${esc(f.src)}):</p><ol style="margin:0 0 6px 18px;padding:0">${f.pasos.slice(0,4).map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`+
  (top[1]?`<p class="muted" style="margin:4px 0">También te puede servir «${esc(top[1].titulo)}».</p>`:'')+
  `<div class="muted" style="font-size:12px">Fuentes: ${top.map(x=>`<a href="#" data-a="ay_art" data-k="${x.k}">${esc(x.titulo)}</a>`).join(' · ')}</div>`}
 else if(!per){a+=`<p>No encontré un artículo de la ayuda que responda esto, así que prefiero no adivinar.</p>`}
 const id=nid('ayl');t.ay_log.unshift({id,ts:new Date().toISOString(),uid:me().id,usuario:me().nombre,rol:me().rolId,pregunta:q.slice(0,300),fuentes:top.map(x=>x.titulo),ok,pantalla:ui.ay_ctx||'',voto:0,derivada:''});cap(t.ay_log,500);
 regBusq(q,top.length,'asistente');
 a+=`<div class="row" style="gap:6px;margin-top:8px;flex-wrap:wrap"><span class="muted" style="font-size:12px">¿Te sirvió?</span><button class="btn s" data-a="ay_lvoto" data-id="${id}" data-v="1">Sí</button><button class="btn s" data-a="ay_lvoto" data-id="${id}" data-v="-1">No</button><button class="btn s" data-a="ay_derivar" data-q="${esc(q)}" data-l="${id}">Derivar a RRHH</button></div>`;
 return a}

/* ---------- configuración (administrador) ---------- */
function vConfig(){const tabs=[...(can(PC)?[['asis','Asistente']]:[]),...(can(PO)?[['art','Artículos de la organización']]:[]),...(can(PI)||can(PC)?[['cons','Consultas']]:[])];
 let tab=U('ay_ctab',tabs[0][0]);if(!tabs.some(t=>t[0]===tab))tab=ui.ay_ctab=tabs[0][0];
 const tb=`<div class="tabs">${tabs.map(t=>`<button class="tab ${t[0]===tab?'on':''}" data-a="ay_ctab" data-t="${t[0]}">${t[1]}</button>`).join('')}</div>`;
 let b='';const c=CFG();
 if(tab==='asis'){const plan=planAllows();
  b=`<div class="panel"><div class="ph"><div><h2>Asistente de ayuda</h2><span class="muted">Responde con la ayuda de GestiaHR y los artículos de tu empresa. No consulta datos de colaboradores ni ejecuta acciones.</span></div>${plan?pill('Incluido en tu plan','ok'):pill('No incluido en tu plan','warn')}</div><div class="pb">
  ${plan?'':`<div class="alert"><span class="dot"></span><div><b>Tu plan no incluye el asistente de ayuda.</b><div class="muted">GestiaHR lo habilita por plan. El centro de ayuda funciona igual, sin asistente. Puedes pedirlo en Configuración → Suscripción.</div></div></div>`}
  <label class="row" style="margin:6px 0 14px;gap:8px;flex-wrap:nowrap;align-items:flex-start"><input type="checkbox" class="chk" data-ayc="on" ${c.asistente?'checked':''} ${plan?'':'disabled'} style="margin-top:3px"><span><b>Asistente encendido para la organización</b><br><span class="muted">Si lo apagas, desaparece para todos; el centro de ayuda sigue disponible.</span></span></label>
  <div class="muted" style="margin-bottom:6px">Roles que pueden usarlo:</div>
  <div class="grid g2" style="gap:6px 16px">${T().roles.map(r=>`<label class="row" style="gap:8px;flex-wrap:nowrap"><input type="checkbox" class="chk" data-ayr="${r.id}" ${c.roles.includes(r.id)?'checked':''} ${plan&&c.asistente?'':'disabled'}><span>${esc(r.nombre)}</span></label>`).join('')}</div>
  <div style="margin-top:14px;display:flex;flex-direction:column;gap:8px"><div><span class="muted">Límite de preguntas por persona al día:</span> <b>${c.limite?c.limite:'Sin límite'}</b></div><div><span class="muted">Aviso que ven los usuarios:</span> ${esc(c.aviso)}</div><div><span class="muted">Último cambio:</span> ${c.act?fd(c.act)+' · '+esc(c.por):'Sin cambios'}</div></div>
  <div class="row"><button class="btn" data-a="ay_cfgEdit">Editar límite y aviso</button></div></div></div>
  <div class="note">Cada cambio queda en Seguridad → Auditoría. Con el asistente apagado no aparece en ninguna pantalla; la ayuda y el buscador siguen disponibles para todos.</div>`}
 else if(tab==='art'){const L=T().ay_org.filter(a=>a.estado!=='Archivado'||ui.ay_arch);
  b=`<div class="row" style="justify-content:space-between;margin-bottom:10px"><span class="muted">Políticas y guías propias. Las ven la ayuda y el asistente, según la audiencia.</span><div class="row"><label class="row" style="gap:6px;flex-wrap:nowrap"><input type="checkbox" class="chk" data-chk="ay_arch" ${ui.ay_arch?'checked':''}><span>Ver archivados</span></label><button class="btn p" data-a="ay_orgNew">Nuevo artículo</button></div></div>`+
  (L.length?`<div class="panel"><div class="tw"><table><thead><tr><th>Artículo</th><th>Audiencia</th><th>Responsable</th><th>Revisión</th><th>Versión</th><th>Estado</th><th></th></tr></thead><tbody>${L.map(a=>{const v=VOT()['o:'+a.id]||{},si=Object.values(v).filter(x=>x>0).length,no=Object.values(v).filter(x=>x<0).length;
   return `<tr><td style="min-width:200px"><b>${esc(a.titulo)}</b><div class="muted">${esc(a.categoria)} · ${si} útil, ${no} no útil</div></td><td>${a.audiencia.includes('todos')?'Toda la organización':a.audiencia.map(ROLN).map(esc).join(', ')}</td><td>${esc(a.responsable)}</td><td class="num">${a.revision?fd(a.revision):'—'}</td><td class="num">${a.version}</td><td>${porRevisar(a)?pill('Por revisar','warn'):pill(a.estado,a.estado==='Publicado'?'ok':'')}</td>
   <td><div class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn s" data-a="ay_orgEdit" data-id="${a.id}">Editar</button>${a.estado!=='Publicado'||porRevisar(a)?`<button class="btn s p" data-a="ay_orgPub" data-id="${a.id}">Publicar</button>`:''}${a.estado!=='Archivado'?`<button class="btn s" data-a="ay_orgArch" data-id="${a.id}">Archivar</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div></div>`
   :emptyState('Tu empresa aún no publicó artículos','Publica tu reglamento interno, la política de vacaciones o la de gastos: la ayuda y el asistente los usarán.','<button class="btn p" data-a="ay_orgNew">Nuevo artículo</button>'))}
 else{const lg=T().ay_log,n=lg.length,ok=lg.filter(l=>l.ok).length,vp=lg.filter(l=>l.voto>0).length,vn=lg.filter(l=>l.voto<0).length,dv=T().ay_der.length;
  const sr={};T().ay_busq.filter(b=>!b.n).forEach(b=>{const k=nrm(b.q).trim();if(!k)return;sr[k]=sr[k]||{q:b.q,n:0,ult:b.ts};sr[k].n++});const srs=Object.values(sr).sort((a,b)=>b.n-a.n).slice(0,10);
  b=`<div class="kpis"><div class="kpi"><b class="num">${n}</b><span>Preguntas al asistente</span></div><div class="kpi"><b class="num">${n?Math.round(ok*100/n):0}%</b><span>Respondidas con fuente</span></div><div class="kpi"><b class="num">${vp+vn?Math.round(vp*100/(vp+vn)):0}%</b><span>Valoración positiva</span></div><div class="kpi"><b class="num">${dv}</b><span>Consultas derivadas</span></div></div>
  <div class="grid g2"><div class="panel"><div class="ph"><h2>Búsquedas sin resultado</h2></div><div class="pb">${srs.length?`<div class="tw"><table><thead><tr><th>Texto buscado</th><th>Veces</th></tr></thead><tbody>${srs.map(s=>`<tr><td>${esc(s.q)}</td><td class="num">${s.n}</td></tr>`).join('')}</tbody></table></div><div class="muted" style="font-size:12px;margin-top:6px">Sin datos de la persona: solo el texto, la pantalla y el rol. Úsalo para escribir artículos nuevos.</div>`:'<span class="muted">Todas las búsquedas encontraron artículos.</span>'}</div></div>
  ${derPanel()}<div class="panel" style="grid-column:1/-1"><div class="ph"><h2>Registro del asistente</h2></div><div class="pb">${n?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Pregunta</th><th>Fuentes</th></tr></thead><tbody>${lg.slice(0,15).map(l=>`<tr><td class="num">${fd(l.ts.slice(0,10))}</td><td>${esc(l.usuario)}<div class="muted">${esc(ROLN(l.rol))}</div></td><td style="min-width:180px">${esc(l.pregunta)}</td><td>${l.fuentes.length?l.fuentes.map(esc).join('; '):pill('Sin fuente','warn')}</td></tr>`).join('')}</tbody></table></div>`:'<span class="muted">Aún no hay preguntas.</span>'}</div></div></div>`}
 return pageHead('Configuración','Ayuda y asistente','','Centro de ayuda para todos los roles y asistente de ayuda con IA.')+tb+b}

function derPanel(){const L=T().ay_der.filter(d=>d.destino==='RRHH'&&!d.ticketId);if(!L.length)return '';
 return `<div class="panel" style="grid-column:1/-1"><div class="ph"><div><h2>Consultas derivadas a RRHH</h2><span class="muted">Las que no pasaron por la mesa de ayuda.${modOn('mesa')?'':' Con la mesa de ayuda contratada llegan como solicitud con plazo.'}</span></div></div><div class="tw"><table><thead><tr><th>Persona</th><th>Consulta</th><th>Artículos consultados</th><th>Estado</th><th></th></tr></thead><tbody>${L.map(d=>`<tr><td>${esc(d.usuario)}<div class="muted">${fd(d.ts.slice(0,10))}</div></td><td style="min-width:180px">${esc(d.pregunta)}${d.respuesta?`<div class="note" style="margin-top:6px">${esc(d.respuesta)}</div>`:''}</td><td>${d.articulos.length?d.articulos.map(esc).join('; '):'—'}</td><td>${pill(d.estado,d.estado==='Respondida'?'ok':'acc')}</td><td>${d.estado!=='Respondida'&&can(PO)?`<button class="btn s p" data-a="ay_derResp" data-id="${d.id}">Responder</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}

/* ---------- consola SaaS: ayuda del producto ---------- */
function sProd(){ensureFlag();const P=PROD(),sop=db.ay_soporte=db.ay_soporte||[];const sr={};
 db.tenants.forEach(t=>((db.data[t.id]||{}).ay_busq||[]).filter(b=>!b.n).forEach(b=>{const k=nrm(b.q).trim();if(!k)return;sr[k]=sr[k]||{q:b.q,n:0,orgs:new Set()};sr[k].n++;sr[k].orgs.add(t.nombre)}));
 const srs=Object.values(sr).sort((a,b)=>b.n-a.n).slice(0,10);
 return `<div class="head"><div><h1>Ayuda del producto</h1><p class="muted">Artículos que ven todas las organizaciones según su plan, sus módulos y el rol de cada usuario.</p></div><div class="row"><button class="btn p" data-a="ay_pNew">Nuevo artículo</button></div></div>
 <div class="panel"><div class="tw"><table><thead><tr><th>Artículo</th><th>Módulo</th><th>Roles</th><th>Pantallas</th><th>Versión</th><th>Estado</th><th></th></tr></thead><tbody>${P.map(a=>`<tr><td style="min-width:200px"><b>${esc(a.titulo)}</b><div class="muted">${esc(a.tipo)} · ${a.hist.length} versión(es) anterior(es)</div></td><td>${esc(MODL[a.modulo]||a.modulo)}</td><td>${a.roles.includes('todos')?'Todos':a.roles.length+' roles'}</td><td class="mono">${a.rutas.map(esc).join(', ')||'—'}</td><td class="num">${esc(a.version)}</td><td>${pill(a.estado,a.estado==='Publicado'?'ok':'')}</td><td><div class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn s" data-a="ay_pEdit" data-id="${a.id}">Editar</button>${a.estado!=='Publicado'?`<button class="btn s p" data-a="ay_pPub" data-id="${a.id}">Publicar</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>
 <div class="grid g2"><div class="panel"><div class="ph"><h2>Búsquedas sin resultado (todas las organizaciones)</h2></div><div class="pb">${srs.length?`<div class="tw"><table><thead><tr><th>Texto</th><th>Veces</th><th>Organizaciones</th></tr></thead><tbody>${srs.map(s=>`<tr><td>${esc(s.q)}</td><td class="num">${s.n}</td><td>${s.orgs.size}</td></tr>`).join('')}</tbody></table></div>`:'<span class="muted">Sin búsquedas fallidas registradas.</span>'}</div></div>
 <div class="panel"><div class="ph"><h2>Consultas de soporte</h2></div><div class="pb">${sop.length?`<div class="tw"><table><thead><tr><th>Organización</th><th>Consulta</th><th>Estado</th><th></th></tr></thead><tbody>${sop.map(s=>`<tr><td>${esc(s.org)}<div class="muted">${esc(s.usuario)} · ${fd(s.ts.slice(0,10))}</div></td><td style="min-width:180px">${esc(s.pregunta)}${s.respuesta?`<div class="note" style="margin-top:6px">${esc(s.respuesta)}</div>`:''}</td><td>${pill(s.estado,s.estado==='Respondida'?'ok':'acc')}</td><td>${s.estado!=='Respondida'?`<button class="btn s p" data-a="ay_supResp" data-id="${s.id}">Responder</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<span class="muted">Las consultas que envíen los administradores desde la ayuda llegan aquí.</span>'}</div></div></div>`}

/* ---------- acciones ---------- */
const ROLES_P=[['todos','Todos los roles'],['r_admin','Administrador empresa'],['r_rrhh','RRHH'],['r_pay','Payroll'],['r_rec','Recruiter'],['r_mgr','Manager'],['r_emp','Empleado'],['r_aud','Auditor'],['r_sst','SST'],['r_inv','Investigador de denuncias']];
function findK(k){return fuentes().find(f=>f.k===k)}
function derivar(q,lid,destino){const t=T(),r=myRel();
 openForm(()=>({title:destino==='sop'?'Escribir al soporte de GestiaHR':'Derivar a RRHH',ok:'Enviar',note:destino==='sop'?'Llega a la consola de GestiaHR con tu nombre y tu organización.':'Llega a RRHH como solicitud, con tu pregunta y los artículos que consultaste.',fields:[{k:'q',l:'Tu consulta',type:'textarea',req:1,full:1}],
  submit:o=>{if(String(o.q).trim().length<8)return 'Cuéntanos un poco más (al menos 8 caracteres).';
   const ts=new Date().toISOString(),consult=(t.ay_log.find(l=>l.id===lid)||{}).fuentes||[];
   const d={id:nid('ayd'),ts,uid:me().id,usuario:me().nombre,pregunta:o.q,pantalla:ui.ay_ctx||'',articulos:consult,destino:destino==='sop'?'Soporte de GestiaHR':'RRHH',estado:'Enviada',codigo:'',respuesta:''};
   if(destino==='sop'){const s={id:nid('ays'),ts,tid:session.tenantId,org:tenant().nombre,usuario:me().nombre,pregunta:o.q,estado:'Enviada',respuesta:'',derId:d.id};(db.ay_soporte=db.ay_soporte||[]).unshift(s);d.codigo='Soporte '+s.id.toUpperCase()}
   else if(modOn('mesa')&&r&&Array.isArray(t.tickets)&&t.ex_cfg&&t.ex_cfg.sla){const cat='Consulta',k={id:nid('ext'),codigo:'HR-'+String(++t.ex_cfg.tkSeq).padStart(4,'0'),relId:r.id,categoria:cat,asunto:'Ayuda: '+(o.q.length>60?o.q.slice(0,57)+'…':o.q),detalle:o.q+(consult.length?'\n\nArtículos consultados: '+consult.join('; '):''),estado:'Nuevo',creado:ts,venceSla:new Date(Date.now()+(t.ex_cfg.sla[cat]||72)*36e5).toISOString(),agenteId:'',mensajes:[{ts,rol:'col',autor:me().nombre+' (desde la ayuda)',texto:o.q}],resuelto:'',cerrado:'',calif:0,califNota:'',reaperturas:0,docId:'',pausa:'',kbIds:[],canal:'Ayuda'};
    t.tickets.push(k);d.codigo=k.codigo;d.ticketId=k.id;emit('ticket.created',{ticket:k})}
   else if(!r&&destino!=='sop')return 'Tu usuario no tiene ficha de colaborador: no puede derivar a RRHH. Escribe a tu contacto en la organización.';
   t.ay_der.unshift(d);const l=t.ay_log.find(x=>x.id===lid);if(l)l.derivada=d.id;
   log('Consulta derivada desde la ayuda','Centro de ayuda',d.destino+(d.codigo?' · '+d.codigo:''),r?r.id:'','',o.q.slice(0,80));ui.ay_tab='mis';toast('Consulta enviada a '+d.destino)}}),{q:q||''})}
function orgForm(id){const a=id?T().ay_org.find(x=>x.id===id):null;
 openForm(()=>({title:a?'Editar «'+a.titulo+'»':'Nuevo artículo de la organización',note:'Escribe la primera línea como resumen y cada paso o punto en una línea aparte. Al publicar se crea una versión nueva.',fields:[{k:'titulo',l:'Título',req:1,full:1},{k:'categoria',l:'Categoría',opts:['Vacaciones y permisos','Asistencia','Planilla','Gastos','Conducta y reglamento','Beneficios','Otro'],req:1,keep:1},{k:'responsable',l:'Responsable',req:1},{k:'revision',l:'Próxima revisión',type:'date',req:1},{k:'audiencia',l:'Audiencia',type:'checks',opts:ROLES_P.filter(r=>r[0]==='todos'||T().roles.some(x=>x.id===r[0])),full:1},{k:'cuerpo',l:'Contenido',type:'textarea',req:1,full:1}],
  submit:o=>{if(String(o.cuerpo).split('\n').filter(Boolean).length<2)return 'Escribe al menos un resumen y un punto, cada uno en su línea.';if(!(o.audiencia||[]).length)return 'Elige al menos una audiencia.';if(o.revision<TODAY)return 'La próxima revisión debe ser hoy o una fecha futura.';
   const aud=o.audiencia.includes('todos')?['todos']:o.audiencia;
   if(a){const antes=a.titulo+' · v'+a.version;Object.assign(a,{titulo:o.titulo,categoria:o.categoria,responsable:o.responsable,revision:o.revision,audiencia:aud,cuerpo:o.cuerpo,estado:'Borrador'});log('Edición de artículo','Centro de ayuda',a.titulo,'',antes,'Borrador pendiente de publicar')}
   else{const n={id:nid('ayo'),titulo:o.titulo,categoria:o.categoria,responsable:o.responsable,revision:o.revision,audiencia:aud,cuerpo:o.cuerpo,version:0,estado:'Borrador',hist:[],actualizado:TODAY};T().ay_org.push(n);log('Alta de artículo','Centro de ayuda',n.titulo,'','','Borrador')}
   toast('Guardado como borrador: publícalo para que lo vean')}}),a?{...a}:{audiencia:['todos'],responsable:me().nombre,revision:addDays(TODAY,180),categoria:'Vacaciones y permisos'})}
function prodForm(id){const P=PROD(),a=id?P.find(x=>x.id===id):null;
 openForm(()=>({title:a?'Editar «'+a.titulo+'»':'Nuevo artículo del producto',note:'Primera línea: resumen. Cada línea siguiente: un paso. Al publicar se guarda la versión anterior.',fields:[{k:'titulo',l:'Título',req:1,full:1},{k:'modulo',l:'Módulo',opts:Object.entries(MODL).filter(e=>e[0]!=='ia').map(e=>[e[0],e[1]]),req:1,keep:1},{k:'tipo',l:'Tipo',opts:['Guía','Pantalla','Preguntas frecuentes','Novedades'],req:1,keep:1},{k:'rutas',l:'Claves de pantalla (separadas por coma)',full:1},{k:'roles',l:'Roles',type:'checks',opts:ROLES_P,full:1},{k:'claves',l:'Palabras clave para la búsqueda',full:1},{k:'cuerpo',l:'Contenido',type:'textarea',req:1,full:1}],
  submit:o=>{const ls=String(o.cuerpo).split('\n').map(s=>s.trim()).filter(Boolean);if(ls.length<2)return 'Escribe un resumen y al menos un paso.';if(!(o.roles||[]).length)return 'Elige al menos un rol.';
   const d={titulo:o.titulo,modulo:o.modulo,tipo:o.tipo,rutas:String(o.rutas||'').split(',').map(s=>s.trim()).filter(Boolean),roles:o.roles.includes('todos')?['todos']:o.roles,claves:o.claves||'',resumen:ls[0],pasos:ls.slice(1),estado:'Borrador'};
   if(a)Object.assign(a,d);else P.push({id:nid('ap'),version:VER,hist:[],actualizado:TODAY,...d});db.saasLog.unshift({ts:new Date().toISOString(),t:'Ayuda del producto: «'+o.titulo+'» guardado como borrador',cat:'Ayuda'});toast('Guardado como borrador')}}),
  a?{titulo:a.titulo,modulo:a.modulo,tipo:a.tipo,rutas:a.rutas.join(', '),roles:a.roles,claves:a.claves,cuerpo:[a.resumen,...a.pasos].join('\n')}:{modulo:'base',tipo:'Guía',roles:['todos']})}
const TOUR={r_admin:['Configura tu organización en Configuración → Centro de configuración.','Crea usuarios y roles en Seguridad.','Decide si el asistente de ayuda está encendido en Configuración → Ayuda y asistente.','Revisa la auditoría cuando lo necesites.'],
 r_rrhh:['Registra y busca colaboradores en Personas.','Atiende las solicitudes en Pendientes y en la Mesa de ayuda.','Publica las políticas de tu empresa en Configuración → Ayuda y asistente.'],
 r_pay:['Calcula la planilla en Nómina → Planilla.','Revisa diferencias antes de enviar a aprobación.','Publica las boletas al cerrar.'],
 r_mgr:['Mira a tu equipo desde Inicio.','Aprueba vacaciones y permisos en Pendientes.','Revisa el calendario del equipo antes de aprobar.'],
 r_emp:['Pide vacaciones y permisos en Tiempo.','Consulta tus boletas en Nómina → Mis boletas.','Usa el botón de ayuda cuando tengas una duda.'],
 _:['Tu menú muestra solo lo que tu rol puede usar.','El botón de ayuda abre los artículos de la pantalla en la que estás.','Si algo no te queda claro, deriva tu duda a RRHH desde la ayuda.']};
function tour(){const p=TOUR[me().rolId]||TOUR._;openModal('Recorrido para '+esc(role().nombre),`<ol style="margin:0 0 0 18px;padding:0">${p.map(x=>`<li style="margin:6px 0">${esc(x)}</li>`).join('')}</ol><p class="muted">Puedes volver a verlo desde Ayuda → Guías.</p>`,`<button class="btn p" data-a="ay_tourOk" data-s="completed">Entendido</button>`)}

const actions={
 ay_open:()=>{if(ui.route!=='ay_centro')ui.ay_ctx=ui.route;ui.ay_tab='pant';go('ay_centro')},
 ay_volver:()=>go(ui.ay_ctx&&rutaOk(ui.ay_ctx)?ui.ay_ctx:'inicio'),
 ay_tab:d=>{ui.ay_tab=d.t;render()},
 ay_ctab:d=>{ui.ay_ctab=d.t;render()},
 ay_qx:()=>{ui.ay_q='';render()},
 ay_ir:d=>{closeM();go(d.r)},
 ay_art:d=>{const f=findK(d.k);if(!f)return toast('El artículo ya no está disponible');openModal(esc(f.titulo),artCard(f),'')},
 ay_voto:d=>{const v=VOT()[d.k]=VOT()[d.k]||{},n=+d.v;v[me().id]=v[me().id]===n?0:n;save();closeM();render();toast(n>0?'Gracias: nos ayuda a saber qué funciona':'Gracias: usaremos tu respuesta para mejorar el artículo')},
 ay_preguntar:d=>{ui.ay_tab='asis';const ch=U('ay_chat',[]);ch.push({q:d.q,a:responder(d.q)});save();render()},
 ay_ask:()=>{const el=$('ay_pq'),q=el?el.value.trim():'';if(!q)return toast('Escribe tu pregunta');if(!asistOn())return toast('El asistente no está disponible para tu rol');
  const lim=CFG().limite;if(lim&&hoyN()>=lim){ui.ay_tab='guias';ui.ay_q=q;render();return toast('Llegaste al límite de preguntas de hoy: te mostramos la búsqueda normal')}
  const ch=U('ay_chat',[]);ch.push({q,a:responder(q)});save();render();setTimeout(()=>{const c=$('ay_conv');if(c)c.lastElementChild&&c.lastElementChild.scrollIntoView({block:'nearest'});const i=$('ay_pq');if(i)i.focus()},0)},
 ay_lvoto:d=>{const l=T().ay_log.find(x=>x.id===d.id);if(l){l.voto=+d.v;save();toast(+d.v>0?'Gracias por tu valoración':'Gracias: revisaremos esta respuesta')}},
 ay_derivar:d=>derivar(d.q,d.l,'rrhh'),
 ay_soporte:d=>{if(!can(PC))return;derivar(d.q,d.l,'sop')},
 ay_tour:()=>tour(),
 ay_tourOk:d=>{T().ay_tour[me().id]=d.s;closeM();save();render()},
 ay_tourSkip:()=>{T().ay_tour[me().id]='skipped';save();render()},
 ay_cfgEdit:()=>{if(!can(PC))return;const c=CFG();openForm(()=>({title:'Límite y aviso del asistente',fields:[{k:'limite',l:'Preguntas por persona al día (0 = sin límite)',type:'number',req:1},{k:'aviso',l:'Aviso que ven los usuarios',type:'textarea',req:1,full:1}],
  submit:o=>{const n=Number(o.limite);if(!(n>=0)||n>500||!Number.isInteger(n))return 'El límite debe ser un número entero entre 0 y 500.';const a='Límite '+c.limite+' · '+c.aviso.slice(0,40);c.limite=n;c.aviso=o.aviso;c.act=TODAY;c.por=me().nombre;log('Cambio del asistente de ayuda','Centro de ayuda','Límite y aviso','',a,'Límite '+n+' · '+o.aviso.slice(0,40));toast('Asistente actualizado')}}),{limite:c.limite,aviso:c.aviso})},
 ay_orgNew:()=>{if(can(PO))orgForm()},
 ay_orgEdit:d=>{if(can(PO))orgForm(d.id)},
 ay_orgPub:d=>{if(!can(PO))return;const a=T().ay_org.find(x=>x.id===d.id);if(a.version)a.hist.unshift({version:a.version,fecha:a.actualizado,titulo:a.titulo});a.version++;a.estado='Publicado';a.actualizado=TODAY;if(a.revision<TODAY)a.revision=addDays(TODAY,180);log('Publicación de artículo','Centro de ayuda',a.titulo,'','','Versión '+a.version);save();render();toast('Publicado: versión '+a.version)},
 ay_orgArch:d=>{if(!can(PO))return;const a=T().ay_org.find(x=>x.id===d.id);confirmBox('Archivar artículo','«'+esc(a.titulo)+'» dejará de verse en la ayuda y en el asistente. Sus versiones se conservan.','Archivar',()=>{const e=a.estado;a.estado='Archivado';log('Archivo de artículo','Centro de ayuda',a.titulo,'',e,'Archivado')})},
 ay_pNew:()=>prodForm(),
 ay_pEdit:d=>prodForm(d.id),
 ay_pPub:d=>{const a=PROD().find(x=>x.id===d.id);a.hist.unshift({version:a.version,fecha:a.actualizado,titulo:a.titulo});a.version=VER;a.estado='Publicado';a.actualizado=TODAY;db.saasLog.unshift({ts:new Date().toISOString(),t:'Ayuda del producto: publicado «'+a.titulo+'»',cat:'Ayuda'});save();render();toast('Publicado para todas las organizaciones')},
 ay_derResp:d=>{if(!can(PO))return;const x=T().ay_der.find(y=>y.id===d.id);openForm(()=>({title:'Responder a '+x.usuario,fields:[{k:'r',l:'Respuesta',type:'textarea',req:1,full:1}],submit:o=>{x.respuesta=o.r;x.estado='Respondida';log('Respuesta a consulta de ayuda','Centro de ayuda',x.pregunta.slice(0,60),'','Enviada','Respondida');toast('Respuesta enviada a '+x.usuario)}}),{})},
 ay_supResp:d=>{const s=(db.ay_soporte||[]).find(x=>x.id===d.id);openForm(()=>({title:'Responder a '+s.org,fields:[{k:'r',l:'Respuesta',type:'textarea',req:1,full:1}],submit:o=>{s.respuesta=o.r;s.estado='Respondida';const dd=((db.data[s.tid]||{}).ay_der||[]).find(x=>x.id===s.derId);if(dd){dd.respuesta=o.r;dd.estado='Respondida'}db.saasLog.unshift({ts:new Date().toISOString(),t:'Soporte: respondida la consulta de '+s.org,cat:'Ayuda'});toast('Respuesta enviada')}}),{})}};

/* interruptores de la configuración y campos de texto (sin perder el foco) */
document.addEventListener('change',e=>{const d=e.target.dataset||{};if(d.ayc==null&&d.ayr==null)return;if(!session||session.saas||!can(PC))return;const c=CFG();
 if(d.ayc!=null){if(!planAllows()){e.target.checked=false;return toast('Tu plan no incluye el asistente de ayuda')}const on=e.target.checked;c.asistente=on;c.act=TODAY;c.por=me().nombre;log('Cambio del asistente de ayuda','Centro de ayuda','Asistente de ayuda','',on?'Apagado':'Encendido',on?'Encendido':'Apagado');toast(on?'Asistente encendido':'Asistente apagado')}
 else{const id=d.ayr,on=e.target.checked,a=c.roles.length;c.roles=on?[...new Set([...c.roles,id])]:c.roles.filter(x=>x!==id);c.act=TODAY;c.por=me().nombre;log('Cambio del asistente de ayuda','Centro de ayuda','Rol '+ROLN(id),'',on?'No habilitado':'Habilitado',on?'Habilitado':'No habilitado');toast('Roles del asistente actualizados')}
 save();render()});
document.addEventListener('input',e=>{if(e.target.id!=='ay_q')return;const v=e.target.value,pos=e.target.selectionStart;clearTimeout(ui.ay_qt);ui.ay_q=v;render();const el=$('ay_q');if(el){el.focus();try{el.setSelectionRange(pos,pos)}catch(x){}}
 ui.ay_qt=setTimeout(()=>{if(v.trim().length>=3&&session&&!session.saas){const n=buscar(v).length;regBusq(v,n,'buscador');save()}},900)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='ay_pq'){e.preventDefault();actions.ay_ask()}});

function init(t,tid){try{ensureFlag()}catch(e){}t.ay_org=t.ay_org||[];t.ay_log=t.ay_log||[];t.ay_busq=t.ay_busq||[];t.ay_der=t.ay_der||[];t.ay_votos=t.ay_votos||{};t.ay_tour=t.ay_tour||{};
 t.ay_cfg=t.ay_cfg||{asistente:tid==='t1',roles:(t.roles||[]).map(r=>r.id).filter(x=>x!=='r_prov'),limite:20,aviso:'El asistente responde con la ayuda de GestiaHR y las políticas de tu empresa, cita sus fuentes y no consulta tus datos personales. Si no sabe, te lo dice.',act:'',por:''};
 if(tid!=='t1')return;
 const o=(titulo,categoria,audiencia,cuerpo,revision,version)=>t.ay_org.push({id:nid('ayo'),titulo,categoria,responsable:'Carmen Huamán Rojas',revision,audiencia,cuerpo,version,estado:'Publicado',hist:[],actualizado:addDays(TODAY,-40)});
 o('Política de vacaciones del Grupo Andino','Vacaciones y permisos',['todos'],'Las vacaciones se programan con tu jefe y se piden con anticipación desde GestiaHR.\nPide tus vacaciones al menos con quince días de anticipación, salvo emergencias.\nPuedes fraccionar tus vacaciones según la ley; los bloques los acuerdas con tu jefe.\nEn diciembre se priorizan los turnos de cierre: coordina con tu área.',addDays(TODAY,120),2);
 o('Licencias y permisos con goce','Vacaciones y permisos',['todos'],'La empresa otorga permisos con goce para situaciones familiares importantes.\nFallecimiento de un familiar directo: licencia con goce; avisa a tu jefe y registra la ausencia con el sustento.\nMatrimonio y nacimiento: según la ley y el reglamento interno; registra la ausencia en Tiempo.\nCitas médicas: registra el permiso y adjunta la constancia.',addDays(TODAY,90),1);
 o('Horario, tolerancia y trabajo remoto','Asistencia',['todos'],'El horario de oficina es de lunes a viernes; tu horario exacto está en tu ficha.\nLa tolerancia de ingreso la fija la política de tiempo de tu sede.\nEl trabajo remoto se acuerda por escrito y se marca desde la aplicación.',addDays(TODAY,-5),3);
 o('Política de gastos y viáticos','Gastos',['todos'],'Los gastos de trabajo se reembolsan con comprobante válido.\nRegistra el gasto en GestiaHR con la foto del comprobante.\nLos viáticos se rinden al volver del viaje.',addDays(TODAY,60),1);
 o('Guía interna de cierre de planilla','Planilla',['r_pay','r_admin'],'Pasos internos del equipo de nómina para cerrar el mes.\nRecibir incidencias de todas las sedes hasta la fecha de corte.\nCalcular, revisar diferencias y enviar a aprobación del gerente de Administración.\nPublicar boletas y archivos bancarios después de la aprobación.',addDays(TODAY,150),2);
 const L=(d,uid,usuario,rol,pregunta,fu,ok,voto)=>t.ay_log.push({id:nid('ayl'),ts:addDays(TODAY,-d)+'T10:00:00.000Z',uid,usuario,rol,pregunta,fuentes:fu,ok,pantalla:'',voto,derivada:''});
 L(1,'us5','Sofía Navarro Poma','r_emp','¿cómo pido vacaciones?',['Cómo pedir vacaciones','Política de vacaciones del Grupo Andino'],true,1);
 L(2,'us4','Martín Gutiérrez León','r_mgr','¿cómo apruebo un permiso de mi equipo?',['Cómo aprobar las solicitudes de tu equipo'],true,1);
 L(3,'us5','Sofía Navarro Poma','r_emp','¿puedo cambiar mi AFP?',[],false,-1);
 L(4,'us3','Milagros Torres Luna','r_pay','pasos para cerrar la planilla',['Calcular, aprobar y cerrar la planilla del mes','Guía interna de cierre de planilla'],true,1);
 [['cambiar de afp',3],['adelanto de sueldo',2],['seguro vida ley',1]].forEach(([q,n])=>{for(let i=0;i<n;i++)t.ay_busq.push({ts:addDays(TODAY,-i-1)+'T09:00:00.000Z',q,pantalla:'',rol:'r_emp',n:0,src:'buscador'})})}

registerModule({id:'ayuda',nombre:'Centro de ayuda',siempre:true,
 perms:[[PV,'Centro de ayuda','Ver la ayuda del producto y de la organización'],[PO,'Centro de ayuda','Publicar los artículos de la organización'],[PC,'Centro de ayuda','Encender, apagar y configurar el asistente de ayuda'],[PI,'Centro de ayuda','Ver indicadores de uso de la ayuda']],
 rolePerms:{r_rrhh:[PV,PO,PI],r_pay:[PV],r_mgr:[PV],r_emp:[PV],r_aud:[PV,PI],r_rec:[PV],r_sst:[PV],r_inv:[PV],r_estudio:[PV],r_prov:[PV]},
 nav:[{grupo:'Configuración',items:[['ay_config','Ayuda y asistente',()=>can(PC)||can(PO)||can(PI)]]}],
 detail:['ay_centro'],titulos:{ay_centro:'Centro de ayuda'},
 views:{ay_centro:vCentro,ay_config:vConfig},actions,init,
 topbar(){return [{a:'ay_open',d:{},icono:'help',label:'Ayuda'}]},
 home(){const s=T().ay_tour&&T().ay_tour[me().id];if(s)return '';return `<div class="panel"><div class="ph"><div><h2>Bienvenido a GestiaHR</h2><span class="muted">Un recorrido corto por lo que puedes hacer con tu rol. El botón de ayuda está arriba en todas las pantallas.</span></div><div class="row"><button class="btn s p" data-a="ay_tour">Ver recorrido</button><button class="btn s" data-a="ay_tourSkip">Saltar</button></div></div></div>`},
 pend(){if(!can(PO))return[];return T().ay_der.filter(d=>d.destino==='RRHH'&&!d.ticketId&&d.estado==='Enviada').map(d=>({id:d.id,tipo:'Consulta de ayuda',t:d.pregunta.length>70?d.pregunta.slice(0,67)+'…':d.pregunta,d:'Derivada por '+d.usuario+' desde la ayuda',abrir:{r:'ay_config'}}))},
 saasTabs:[['ay_prod','Ayuda del producto',sProd]],
 api:{asistOn,planAllows,buscar}});
})();
